using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // Fix: Explicitly set the old property name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue" in 9.0.
        // Fix: Use HasIdProperty convention or a value generator that preserves the legacy format.
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id");

        // Breaking change 3: Cosmos DB provider does not support indexes (sync will throw in 9.0).
        // Fix: Remove HasIndex — Cosmos uses indexing policies at the container level, not EF indexes.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); // REMOVED
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

