}

arguments.new_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: In EF Core 9 Cosmos provider, SaveChanges now uses bulk/batch operations
        // with optimistic concurrency by default. Existing documents without an _etag will fail.
        // Fix: Either disable optimistic concurrency or ensure documents have _etag values.

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();

        // Breaking change 5: Raw SQL queries like:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // must be updated to:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'
        // OR if you configured HasDiscriminator("Discriminator") as above, the old query still works.
    }
}

